import { Group, Mesh, PlaneGeometry, BoxGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const root = new Group();

  // ---------- Backdrop ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const topColor = vec3(0.1019608, 0.1019608, 0.1372549); // #1a1a22
  const bottomColor = vec3(0.0705882, 0.0705882, 0.0901961); // #121218
  backdropMat.colorNode = mix(topColor, bottomColor, uv().y);
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const kickerItem = items.find(i => i.role === 'kicker' || (i.text && i.text.toUpperCase().includes('AS FEATURED IN')));
  if (kickerItem) {
    const kicker = ctx.fontAtlas.createText(kickerItem.text, {
      fontSize: 9,
      color: '#e8ecf2',
      align: 'center'
    });
    const rows = 2,
      cols = 3,
      tileH = 0.62,
      gap = 0.25;
    const totalH = rows * tileH + (rows - 1) * gap;
    const startY = totalH / 2 - tileH / 2;
    const kickerY = startY + tileH / 2 + 0.3;
    kicker.position.set(0, kickerY, 0);
    root.add(kicker);
  }

  // ---------- Tile Grid ----------
  const tileW = 1.0,
    tileH = 0.62,
    gap = 0.25,
    rows = 2,
    cols = 3;
  const totalW = cols * tileW + (cols - 1) * gap;
  const totalH = rows * tileH + (rows - 1) * gap;
  const startX = -totalW / 2 + tileW / 2;
  const startY = totalH / 2 - tileH / 2;

  const tileGeom = new BoxGeometry(tileW, tileH, 0.02);
  const tiles = [];
  const cleanupTimelines = [];

  const brandItems = items.filter(i => i.role === 'brand-mark' || (i.text && i.text !== (kickerItem?.text)));
  let brandIdx = 0;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const mat = new MeshStandardNodeMaterial();
      mat.metalness = 0.5;
      mat.roughness = 0.55;
      mat.clearcoat = 0.2;
      mat.colorNode = mix(topColor, bottomColor, uv().y);

      const tile = new Mesh(tileGeom, mat);
      const x = startX + c * (tileW + gap);
      const y = startY - r * (tileH + gap);
      tile.position.set(x, y, 0);
      tile.userData.handlers = {};

      const item = brandItems[brandIdx++];
      if (item) {
        const txt = ctx.fontAtlas.createText(item.text, {
          fontSize: 13,
          color: '#e8ecf2',
          align: 'center'
        });
        txt.traverse(child => {
          if (child.isMesh && child.material) {
            child.material.transparent = true;
            child.material.opacity = 0.78;
          }
        });
        txt.position.set(0, 0, 0.03);
        tile.add(txt);

        const hoverTl = gsap.timeline({ paused: true });
        hoverTl.to(tile.position, { z: 0.05, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, 0);
        hoverTl.to(txt.material, { opacity: 1.0, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, 0);
        tile.userData.handlers.hover = enter => {
          if (enter) hoverTl.play();
          else hoverTl.reverse();
        };
        tile.userData.hoverTl = hoverTl;
        cleanupTimelines.push(hoverTl);
      }

      tiles.push(tile);
      root.add(tile);
    }
  }

  // ---------- Entrance Animation ----------
  const entranceTl = gsap.timeline();
  tiles.forEach((tile, idx) => {
    tile.position.y += 0.2;
    tile.traverse(child => {
      if (child.isMesh && child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
      }
    });
    entranceTl.to(
      tile.position,
      { y: tile.position.y - 0.2, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      idx * 0.08
    );
    entranceTl.to(
      tile,
      { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      idx * 0.08
    );
    tile.traverse(child => {
      if (child.isMesh && child.material && child.material.opacity !== undefined) {
        entranceTl.to(
          child.material,
          { opacity: 0.78, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
          idx * 0.08
        );
      }
    });
  });
  cleanupTimelines.push(entranceTl);

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    tiles.forEach(tile => {
      tile.geometry?.dispose();
      if (tile.material?.dispose) tile.material.dispose();
      tile.traverse(child => {
        if (child.isMesh) {
          child.geometry?.dispose();
          if (child.material?.dispose) child.material.dispose();
        }
      });
      if (tile.userData.hoverTl) tile.userData.hoverTl.kill();
    });
    backdrop.geometry?.dispose();
    if (backdrop.material?.dispose) backdrop.material.dispose();
    cleanupTimelines.forEach(tl => tl.kill());
  };

  return root;
}
